-- ----------sql2------------
-- 2147483648, 2147483648
SELECT DISTINCT T3.CITY, T3.COUNTY FROM INCOME AS T1 INNER JOIN MEMBER AS T2 ON T1.LINK_TO_MEMBER = T2.MEMBER_ID INNER JOIN ZIP_CODE AS T3 ON T3.ZIP_CODE = T2.ZIP WHERE T1.AMOUNT > 40;

